        tostring(Widget[CallbackName])
    ));

    if Button == nil then
        UITrace(string.format("BindButton failed, %s is nil", tostring(ButtonName)));
        return false;
    end

    if Button.OnClicked == nil then
        UITrace(string.format("BindButton failed, %s.OnClicked is nil", tostring(ButtonName)));
        return false;
    end

    if Widget[CallbackName] == nil then
        UITrace(string.format("BindButton failed, callback %s is nil", tostring(CallbackName)));
        return false;
    end

    Button.OnClicked:Add(Widget[CallbackName], Widget);
    UITrace(string.format("BindButton success, ButtonName=%s", tostring(ButtonName)));
    return true;
end

